    if(timing!=='beginning'){
      balance+=monthlyDeposit;totalDeposits+=monthlyDeposit;periodDeposits+=monthlyDeposit;
      if(month%12===0){balance+=annualDeposit;totalDeposits+=annualDeposit;periodDeposits+=annualDeposit}
    }
